insert into products (slug, name, description, long_description, category_id, spice_note, dietary, badge, tagline, rating, review_count, published) values ('shahi-kaju-mixture', 'Shahi Kaju Mixture', 'Plump Goan cashews, raisins, and roasted melon seeds blended with crisp hand-spun gram sev.', 'Our signature dry-fruit savory is roasted in small batches with cold-pressed groundnut oil. Whole Goan cashews, green raisins, and melon seeds are folded into hand-spun gram sev for a royal tea-time crunch.', (select id from categories where slug='namkeens'), 'medium', ARRAY['pure-veg','no-palm','jain']::text[], 'Bestseller', 'Dry Fruit Savory', 4.9, 1240, true) on conflict (slug) do update set name=excluded.name, description=excluded.description, long_description=excluded.long_description, category_id=excluded.category_id, spice_note=excluded.spice_note, dietary=excluded.dietary, badge=excluded.badge, tagline=excluded.tagline, rating=excluded.rating, review_count=excluded.review_count, published=true;
