insert into products (slug, name, description, long_description, category_id, spice_note, dietary, badge, tagline, rating, review_count, published) values ('ratlami-sev-hing-bhujia', 'Ratlami Sev & Hing Bhujia', 'Pounded Laung (cloves) and compound Hing from Hathras create our signature tingling crunch.', 'A classic Ratlami recipe pounded with clove, black pepper, and Hathras hing. Fine sev and bhujia strands are fried fresh and nitrogen-sealed for pan-India crispness.', (select id from categories where slug='namkeens'), 'teekha', ARRAY['pure-veg','no-palm','jain']::text[], 'Strong Hing', 'Signature Sev', 4.8, 890, true) on conflict (slug) do update set name=excluded.name, description=excluded.description, long_description=excluded.long_description, category_id=excluded.category_id, spice_note=excluded.spice_note, dietary=excluded.dietary, badge=excluded.badge, tagline=excluded.tagline, rating=excluded.rating, review_count=excluded.review_count, published=true;
