insert into products (slug, name, description, long_description, category_id, spice_note, dietary, badge, tagline, rating, review_count, published) values ('jodhpur-khasta-dal-kachori', 'Jodhpur Khasta Dal Kachori', 'Slow-roasted moong dal, crushed coriander and saunf encased in multilayer flaky desi ghee dough.', 'Hand-rolled khasta shells filled with slow-roasted yellow moong dal, coriander, and saunf. Ready to reheat for tea-time or festive thalis.', (select id from categories where slug='kachoris'), 'medium', ARRAY['pure-veg','cow-ghee','jain']::text[], 'Fresh Batch Today', 'Hot Snack Staple', 4.9, 2110, true) on conflict (slug) do update set name=excluded.name, description=excluded.description, long_description=excluded.long_description, category_id=excluded.category_id, spice_note=excluded.spice_note, dietary=excluded.dietary, badge=excluded.badge, tagline=excluded.tagline, rating=excluded.rating, review_count=excluded.review_count, published=true;
